"use client"

import { Separator as SeparatorPrimitive } from "@base-ui/react/separator"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./separator.css"

function Separator({
  className,
  orientation = "horizontal",
  ...props
}: SeparatorPrimitive.Props) {
  return (
    <SeparatorPrimitive
      data-slot="separator"
      orientation={orientation}
      className={(state) =>
        cn(
          "np-separator",
          typeof className === "function" ? className(state) : className
        )
      }
      {...props}
    />
  )
}

export { Separator }

/* nepui — Separator */

.np-separator,
[data-np-separator] {
  --np-separator-size: 1px;
  --np-separator-color: var(--np-border);
  flex-shrink: 0;
  box-sizing: border-box;
  width: 100%;
  height: var(--np-separator-size);
  margin: 0;
  border: 0;
  background: var(--np-separator-color);
}

.np-separator-vertical,
:is(.np-separator, [data-np-separator])[data-orientation="vertical"] {
  align-self: stretch;
  width: var(--np-separator-size, 1px);
  height: auto;
}
